import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import RoomCard from "../components/RoomCard";
import Footer from "../components/Footer";

const TESTIMONIALS = [
  { initials: "KM", name: "Khaled M.", date: "Nov 2025", text: "Incredible place! The Nile view is exactly as shown — actually better. Very clean and modern. Definitely coming back.", bg: "#C8D8E8", col: "#2D5473" },
  { initials: "SR", name: "Sara R.",   date: "Oct 2025", text: "Great location — everything is walkable. Kitchen well-stocked and WiFi blazing fast. Self check-in worked flawlessly.", bg: "#D5E8D5", col: "#2D6B2D" },
  { initials: "AM", name: "Ahmed M.", date: "Sep 2025", text: "Best stay in Cairo. The host was incredibly welcoming and the apartment exceeded all expectations. 10/10.", bg: "#E8D5C8", col: "#7A4020" },
];

export default function HomePage() {
  const navigate = useNavigate();
  const [rooms, setRooms] = useState([]);
  const [search, setSearch] = useState({ city: "", guests: "" });

  useEffect(() => {
    axios.get("/api/rooms").then(r => setRooms(r.data.rooms)).catch(() => {});
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    const params = new URLSearchParams();
    if (search.city)   params.set("city", search.city);
    if (search.guests) params.set("maxGuests", search.guests);
    navigate(`/explore?${params.toString()}`);
  };

  return (
    <div>
      {/* ── Hero ── */}
      <section style={{ display: "grid", gridTemplateColumns: "1fr 1fr", minHeight: "calc(100vh - var(--nav-h))", alignItems: "center" }}>
        <div style={{ padding: "80px 60px 80px 80px" }}>
          <span className="sec-label">Egypt's #1 Room Booking Platform</span>
          <h1 className="h1" style={{ marginBottom: 22 }}>
            Your next<br /><em>perfect stay</em><br />is waiting.
          </h1>
          <p style={{ fontSize: 17, color: "var(--muted)", lineHeight: 1.75, marginBottom: 36, maxWidth: 420 }}>
            Browse thousands of verified rooms across Egypt. Book with confidence — every listing is ID-verified and reviewed by real guests.
          </p>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 52 }}>
            <button className="btn btn-dark" onClick={() => navigate("/explore")}>Explore Rooms →</button>
            <button className="btn btn-out"  onClick={() => navigate("/about")}>How it Works</button>
          </div>
          <div style={{ display: "flex", gap: 40 }}>
            {[["12K+","Rooms listed"],["98%","Satisfaction"],["180+","Cities"]].map(([n,l]) => (
              <div key={l}>
                <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 28 }}>{n}</div>
                <div style={{ fontSize: 12, color: "var(--muted)", fontWeight: 500 }}>{l}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Hero Right — illustrated visual */}
        <div style={{
          height: "100%", minHeight: "calc(100vh - var(--nav-h))",
          background: "linear-gradient(145deg,#1C1C1E 0%,#3A2E22 50%,#C8975A 100%)",
          display: "flex", alignItems: "center", justifyContent: "center", position: "relative", overflow: "hidden",
        }}>
          <div style={{ position: "absolute", top: -80, right: -80, width: 320, height: 320, borderRadius: "50%", background: "rgba(200,151,90,.15)" }} />
          <div style={{ position: "absolute", bottom: -40, left: -40, width: 200, height: 200, borderRadius: "50%", background: "rgba(200,151,90,.08)" }} />
          <div style={{ position: "relative", zIndex: 1, textAlign: "center", color: "white" }}>
            <div style={{ fontSize: 80, marginBottom: 16 }}>🏠</div>
            <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 28, marginBottom: 8 }}>Find your stay</div>
            <div style={{ fontSize: 14, color: "rgba(255,255,255,.6)" }}>Verified. Safe. Comfortable.</div>
          </div>
        </div>
      </section>

      {/* ── Search Bar ── */}
      <section style={{ background: "white", borderTop: "1px solid var(--border)", borderBottom: "1px solid var(--border)", padding: "32px 40px" }}>
        <form onSubmit={handleSearch} style={{
          maxWidth: 860, margin: "0 auto", display: "grid",
          gridTemplateColumns: "1.4fr 1fr 1fr auto",
          background: "white", border: "1.5px solid var(--border)",
          borderRadius: "var(--r-xl)", boxShadow: "var(--sh-md)", overflow: "hidden",
        }}>
          {[
            { label: "City", placeholder: "Cairo, Alexandria…", key: "city", type: "text" },
            { label: "Check-in",  placeholder: "Add date", key: "checkin",  type: "date" },
            { label: "Check-out", placeholder: "Add date", key: "checkout", type: "date" },
          ].map(({ label, placeholder, key, type }, i) => (
            <div key={key} style={{
              padding: "16px 20px",
              borderRight: i < 2 ? "1px solid var(--border)" : "none",
            }}>
              <label style={{ display: "block", fontSize: 10, fontWeight: 700, letterSpacing: ".9px", textTransform: "uppercase", color: "var(--muted)", marginBottom: 5 }}>{label}</label>
              <input
                type={type} placeholder={placeholder}
                style={{ border: "none", outline: "none", fontFamily: "'Sora',sans-serif", fontSize: 14, fontWeight: 500, color: "var(--charcoal)", background: "transparent", width: "100%" }}
                onChange={e => setSearch(p => ({ ...p, [key]: e.target.value }))}
              />
            </div>
          ))}
          <div style={{ display: "flex", alignItems: "center", padding: 10 }}>
            <button type="submit" style={{
              background: "var(--charcoal)", color: "white", border: "none",
              width: 46, height: 46, borderRadius: 999,
              display: "flex", alignItems: "center", justifyContent: "center",
              cursor: "pointer", fontSize: 18, transition: "background .15s",
            }} onMouseEnter={e => e.target.style.background = "var(--gold)"}
               onMouseLeave={e => e.target.style.background = "var(--charcoal)"}>🔍</button>
          </div>
        </form>
      </section>

      {/* ── Features ── */}
      <section style={{ padding: "72px 0", background: "var(--cream)" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 40px" }}>
          <div style={{ textAlign: "center", marginBottom: 48 }}>
            <span className="sec-label">Why Roomly</span>
            <h2 className="h2">The safest way to book in Egypt</h2>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 24 }}>
            {[
              { icon: "🪪", title: "ID Verified",    desc: "Every guest verifies their national ID for safe, trusted bookings." },
              { icon: "🔒", title: "Secure Payments", desc: "AES-256 encrypted payments and secure data storage." },
              { icon: "⭐", title: "Real Reviews",    desc: "Only guests who completed a stay can leave reviews." },
              { icon: "📞", title: "24/7 Support",    desc: "Our team is always available to help with your booking." },
            ].map(f => (
              <div key={f.title} style={{ textAlign: "center", padding: "28px 14px" }}>
                <div style={{ width: 52, height: 52, borderRadius: 14, background: "var(--gold-lt)", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>{f.icon}</div>
                <h4 style={{ fontWeight: 600, fontSize: 15, marginBottom: 6 }}>{f.title}</h4>
                <p style={{ fontSize: 13, color: "var(--muted)" }}>{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Featured Rooms ── */}
      <section style={{ background: "white", borderTop: "1px solid var(--border)", padding: "72px 0" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 40px" }}>
          <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginBottom: 36 }}>
            <div>
              <span className="sec-label">Featured Listings</span>
              <h2 className="h2">Top rooms right now</h2>
            </div>
            <button className="btn btn-out" onClick={() => navigate("/explore")}>View all →</button>
          </div>
          {rooms.length === 0 ? (
            <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>
              <div style={{ fontSize: 48, marginBottom: 16 }}>🏠</div>
              <p>No rooms yet. <a href="#" onClick={() => navigate("/explore")} style={{ color: "var(--gold)" }}>Explore</a> or ask admin to add rooms.</p>
            </div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 24 }}>
              {rooms.slice(0, 6).map((room, i) => <RoomCard key={room._id} room={room} index={i} />)}
            </div>
          )}
        </div>
      </section>

      {/* ── Testimonials ── */}
      <section style={{ padding: "72px 0", background: "var(--cream)", borderTop: "1px solid var(--border)" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 40px" }}>
          <div style={{ textAlign: "center", marginBottom: 40 }}>
            <span className="sec-label">Guest Reviews</span>
            <h2 className="h2">What our guests say</h2>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 24 }}>
            {TESTIMONIALS.map(t => (
              <div key={t.name} style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 24 }}>
                <p style={{ fontSize: 14, color: "var(--charcoal)", lineHeight: 1.7, marginBottom: 16, fontStyle: "italic" }}>"{t.text}"</p>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div style={{ width: 38, height: 38, borderRadius: "50%", background: t.bg, color: t.col, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 600 }}>{t.initials}</div>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: 13 }}>{t.name}</div>
                    <div style={{ fontSize: 11, color: "var(--muted)" }}>{t.date}</div>
                  </div>
                  <div style={{ marginLeft: "auto", color: "var(--gold)", fontSize: 13 }}>★★★★★</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── CTA Band ── */}
      <section style={{ background: "var(--charcoal)", color: "white", padding: "72px 40px", textAlign: "center" }}>
        <h2 className="h2" style={{ color: "white", marginBottom: 14 }}>Ready to find your perfect stay?</h2>
        <p style={{ color: "rgba(255,255,255,.6)", fontSize: 16, marginBottom: 32 }}>Join thousands of guests who trust Roomly for their travels across Egypt.</p>
        <button className="btn btn-gold" style={{ fontSize: 15, padding: "14px 36px" }} onClick={() => navigate("/explore")}>
          Explore Rooms →
        </button>
      </section>

      <Footer />
    </div>
  );
}
